// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/scenes/SehraScene.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { Camera, ParallaxLayer, useCamera } from "../camera/Camera";
import { Stage } from "../stage/Stage";
import { SceneLighting } from "../stage/SceneLighting";
import { PaperBackground } from "../paper/PaperBackground";
import { GoldFrame } from "../ornaments/GoldFrame";
import { Cloud, PalaceSkyline, SkyGradient, SunOnWire } from "../sets/Sky";
import { Drape, JaliRailing, JharokhaWall, MarbleLedge } from "../sets/WeddingDayInteriors";
import { people, wardrobe } from "../characters/cast";
import { Figure, Gate, SVG, fig, lerpPt, reachPose, toScene, type Pt } from "../props/WeddingDayKit";
import { Lantern, Thali } from "../props/WeddingDayDecor";
import { Flower, GarlandSwag, Leaf, MarigoldStrand, Petal } from "../props/Florals";
import { Diya } from "../props/Ganesh";
import { FallingPetals } from "../kit/Particles";
import { EventTitle } from "../kit/EventTitle";
import { EASE, mix, prog, wave } from "../kit/motion";
import { palette } from "../theme/palette";
import type { SceneProps } from "./types";
import { bi, whenBi } from "../data/i18n";

// Placement: Rishabh close and large; brothers behind him; Pranab in front with a thali.
const R = fig(people.rishabh, 540, 1850, 1500);
const H = fig(people.hardik, 228, 1640, 1080);
const A = fig(people.ashish, 855, 1650, 1070);
const P = fig(people.pranab, 190, 1870, 1250);

/**
 * Sehra Bandi — a close, intimate morning moment in the jharokha: the brothers raise their
 * hands to the safa and the pearl-and-jasmine sehra falls gracefully over Rishabh's face.
 */
export const SehraScene: React.FC<SceneProps> = ({ inv, dur }) => {
  const frame = useCurrentFrame();
  // Build-up paced in absolute frames; compressed only if the scene is shorter than planned.
  const k = Math.min(1, (dur - 110) / 100);
  const f = (n: number) => n * k;

  const cam = useCamera([
    { frame: 0, scale: 1.0, y: 10, focus: 1 },
    { frame: dur - 6, scale: 1.075, y: -26 },
  ]);

  // brothers' hands: rest → up to the safa rim → hold while the sehra falls → onto his shoulders
  const up = prog(frame, f(14), f(24), EASE.inOut);
  const down = prog(frame, f(84), f(18), EASE.inOut);
  const tieBob = Math.sin(prog(frame, f(42), f(46), EASE.inOut) * Math.PI) * 10;
  const rimL = toScene(R, 108, 112);
  const rimR = toScene(R, 292, 112);
  const shL = toScene(R, 128, 250);
  const shR = toScene(R, 272, 250);
  const hRest: Pt = toScene(H, 290, 560);
  const aRest: Pt = toScene(A, 110, 560);
  const hHand = down > 0 ? lerpPt([rimL[0], rimL[1] + tieBob], shL, down) : lerpPt(hRest, [rimL[0], rimL[1] + tieBob], up);
  const aHand = down > 0 ? lerpPt([rimR[0], rimR[1] + tieBob], shR, down) : lerpPt(aRest, [rimR[0], rimR[1] + tieBob], up);
  const cord = prog(frame, f(32), f(12)) * (1 - prog(frame, f(84), f(12)));
  const hPose = { ...reachPose(H, null, hHand, -1, -1), lShoulder: 8, lElbow: -10, headTilt: 4 + up * 3 };
  const aPose = { ...reachPose(A, aHand, null, 1, 1), rShoulder: -8, rElbow: 10, headTilt: -4 - up * 3 };

  // the sehra falls with a soft settle, strands sway a touch with the head
  const fall = prog(frame, f(40), f(52), EASE.cine);
  const sehra = fall + Math.sin(prog(frame, f(84), f(22)) * Math.PI) * 0.035;
  const headDown = Math.sin(prog(frame, f(34), f(70), EASE.inOut) * Math.PI);
  const rPose = { lShoulder: 13, lElbow: -52, rShoulder: -13, rElbow: 52, headTilt: -2.5 * headDown + wave(frame, 90) * 0.8 };

  // Pranab carries the thali with the sehra's flowers
  const pTray: Pt = toScene(P, 200, 470);
  const pPose = reachPose(P, [pTray[0] - 36, pTray[1] + 8], [pTray[0] + 36, pTray[1] + 8], -1, 1);

  const item = inv.events.weddingDay.items.find((i) => i.id === "sehra");

  return (
    <Stage background="#EAD6B8">
      <Camera state={cam}>
        {/* BACKGROUND — the morning view through the window */}
        <ParallaxLayer depth={0.2} blurStrength={4}>
          <SVG>
            <SkyGradient id="sehra-sky" top="#F6DDB6" mid="#F9E6C4" bottom="#F2CFA2" />
            <Cloud x={620} y={420} w={260} fill="#FCEFD6" line={palette.goldLight} />
            <Cloud x={180} y={760} w={200} fill="#FBEBCF" />
            <SunOnWire t={0.2} drop={40} />
            <PalaceSkyline fill="#E9C9A0" y={1060} accent="#F7E3C2" />
            <PalaceSkyline fill="#DDB287" y={1190} />
          </SVG>
          <PaperBackground stock="cream" seed="sehra-sky" fibres={20} textureOnly />
        </ParallaxLayer>
        <ParallaxLayer depth={0.45} blurStrength={3}>
          <SVG>
            <JaliRailing y={1270} x0={90} x1={990} fill="#EBD5B4" shade="#CDAE88" />
          </SVG>
        </ParallaxLayer>

        {/* ARCHITECTURE — the jharokha wall, drapes, lanterns */}
        <ParallaxLayer depth={0.6} blurStrength={2}>
          <SVG>
            <JharokhaWall wall="#E2C39C" shade="#A87E58" />
            <Drape x={96} y={236} h={1300} w={170} color="#E6BFAE" edge={palette.gold} sway={wave(frame, 160) * 6} />
            <Drape x={984} y={236} h={1300} w={170} color="#E6BFAE" edge={palette.gold} flip sway={wave(frame, 160, 1) * 6} />
            <Lantern x={96} y={-20} len={250} s={1.05} swing={wave(frame, 120) * 1.6} id="sehra-l1" />
            <Lantern x={984} y={-20} len={250} s={1.05} swing={wave(frame, 120, 1.4) * 1.6} id="sehra-l2" />
          </SVG>
        </ParallaxLayer>

        {/* CHARACTERS — brothers behind, the groom close, Pranab in front */}
        <ParallaxLayer depth={0.85} blurStrength={12}>
          <Figure f={H} person={people.hardik} outfit={wardrobe.hardik.wedding} pose={hPose} />
          <Figure f={A} person={people.ashish} outfit={wardrobe.ashish.wedding} pose={aPose} />
        </ParallaxLayer>
        <ParallaxLayer depth={1} blurStrength={3}>
          <Figure f={R} person={people.rishabh} outfit={wardrobe.rishabh.wedding} pose={rPose} sehra={sehra} />
        </ParallaxLayer>
        <ParallaxLayer depth={1} blurStrength={3}>
          <SVG>
            {[
              [hHand, toScene(R, 150, 100)],
              [aHand, toScene(R, 250, 100)],
            ].map(([a, b], i) => (
              <g key={i} opacity={cord}>
                <path d={`M${a[0]} ${a[1]} Q${(a[0] + b[0]) / 2} ${(a[1] + b[1]) / 2 + 26} ${b[0]} ${b[1]}`} fill="none" stroke={palette.maroon} strokeWidth={5} strokeLinecap="round" />
                <path d={`M${a[0]} ${a[1]} Q${(a[0] + b[0]) / 2} ${(a[1] + b[1]) / 2 + 26} ${b[0]} ${b[1]}`} fill="none" stroke={palette.goldLight} strokeWidth={1.6} strokeDasharray="5 5" />
                <circle cx={a[0]} cy={a[1] + 30} r={6} fill="url(#foil)" />
                <path d={`M${a[0]} ${a[1] + 34} L${a[0]} ${a[1] + 70}`} stroke={palette.maroon} strokeWidth={3} />
              </g>
            ))}
          </SVG>
        </ParallaxLayer>
        <ParallaxLayer depth={1.1} blurStrength={3}>
          <Figure f={P} person={people.pranab} outfit={wardrobe.pranab.wedding} pose={{ ...pPose, headTilt: 4 }} />
          <SVG>
            <Thali x={pTray[0]} y={pTray[1]} r={70} tilt={0.42} petals katoris={false} />
            <g transform={`translate(${pTray[0] - 30} ${pTray[1] - 40})`}>
              <Flower x={0} y={10} r={13} tone="rose" />
              <Flower x={26} y={4} r={12} tone="orange" />
              <Flower x={50} y={12} r={11} tone="ivory" />
            </g>
          </SVG>
        </ParallaxLayer>

        {/* soft morning shafts through the window */}
        <ParallaxLayer depth={0.9} blurStrength={0}>
          <SVG>
            <defs>
              <linearGradient id="sehra-shaft" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0" stopColor="#FFF4DC" stopOpacity={0.5} />
                <stop offset="1" stopColor="#FFF4DC" stopOpacity={0} />
              </linearGradient>
            </defs>
            <g opacity={0.35 + wave(frame, 200) * 0.05}>
              <path d="M180 330 L330 300 L900 1600 L560 1640 Z" fill="url(#sehra-shaft)" />
              <path d="M360 290 L430 280 L980 1400 L820 1440 Z" fill="url(#sehra-shaft)" opacity={0.7} />
            </g>
          </SVG>
        </ParallaxLayer>

        {/* FOREGROUND — marble ledge with a diya and petals; marigold ladis at the corners */}
        <ParallaxLayer depth={1.2} blurStrength={0}>
          <SVG>
            <MarbleLedge y={1500} />
            {[150, 330, 760, 930].map((x, i) => (
              <Petal key={x} x={x} y={1560 + (i % 2) * 12} rot={i * 61} s={1.2} color={i % 2 ? palette.rose : palette.marigold} />
            ))}
          </SVG>
          <div style={{ position: "absolute", left: 900, top: 1440 }}>
            <Diya size={110} flicker={frame / 7} />
          </div>
        </ParallaxLayer>
        <ParallaxLayer depth={1.45} blurStrength={0} style={{ filter: "blur(6px)" }}>
          <SVG>
            <GarlandSwag from={[-40, 60]} to={[380, 10]} sag={60} r={20} seed="sehra-fg1" tones={["orange", "yellow", "rose", "orange"]} />
            <GarlandSwag from={[720, 10]} to={[1120, 80]} sag={56} r={20} seed="sehra-fg2" tones={["yellow", "orange", "orange", "rose"]} />
            <MarigoldStrand x={40} y={40} length={420} r={15} seed="sehra-s1" sway={wave(frame, 140) * 6} />
            <MarigoldStrand x={1040} y={60} length={360} r={15} seed="sehra-s2" sway={wave(frame, 140, 2) * 6} />
            <Leaf x={-10} y={1880} rot={-25} s={3} color={palette.greenDeep} />
            <Flower x={50} y={1880} r={42} tone="orange" />
            <Flower x={1040} y={1890} r={40} tone="rose" />
          </SVG>
        </ParallaxLayer>
        <FallingPetals count={10} seed="sehra-petals" speed={0.55} start={-60} opacity={0.75} size={1.1} />
      </Camera>

      <SceneLighting
        warmth={0.42}
        keyX={24}
        keyY={24}
        spots={[
          { x: 22, y: 26, r: 34, color: "#FFE6B0", intensity: 0.24 },
          { x: 50, y: 34, r: 30, color: "#FFF1D2", intensity: mix(0.08, 0.2, fall) },
        ]}
        vignette={0.44}
      />

      <AbsoluteFill>
        <Gate from={f(44)}>
          <EventTitle start={f(44)} kicker="Adorning the Dulha" title={item?.title ?? "Sehra Bandi"} lines={[whenBi(inv.events.weddingDay.date, item?.time), bi(inv.events.weddingDay.venue)]} top={1604} titleSize={100} />
        </Gate>
      </AbsoluteFill>

      <GoldFrame />
    </Stage>
  );
};
